-- Insert Quiz Questions for Lesson: Invite a Repeat Booking

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 21 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 21 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'invite-repeat-booking' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson invite-repeat-booking not found in module 21';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is rebooking typically easier than acquiring a new customer?', 
    '["It requires no marketing budget","Rebooking is always free for the customer","The customer already knows, likes, and trusts you","New customers are not valuable"]'::jsonb,
    'The customer already knows, likes, and trusts you',
    'Rebooking an existing customer is easier because they already have a relationship with you. They understand your value and have experienced your service firsthand, removing the trust-building phase required with new prospects.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How long should you wait after the thank-you message before sending the rebooking invitation?', 
    '["Immediately after the thank-you","Approximately one day","One week","Only if they do not rebook on their own"]'::jsonb,
    'Approximately one day',
    'Wait approximately one day after the thank-you message. This gives the customer breathing room without letting too much time pass. Immediate rebooking feels pushy; waiting too long lets the positive experience fade.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you include in the rebooking message?', 
    '["One clear calendar link and the value of the next session","Multiple calendar links for flexibility","A discount code for first-time customers","A request for payment upfront"]'::jsonb,
    'One clear calendar link and the value of the next session',
    'Include one clear calendar link to remove friction, and explain the value of the next session to give the customer a reason to return. Multiple links create decision paralysis; a single, direct path works best.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

