-- Insert Quiz Questions for Lesson: Ask for Introductions

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 21 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 21 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'ask-for-introductions' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson ask-for-introductions not found in module 21';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When is the best time to ask for a referral?', 
    '["After a positive experience when the customer is satisfied","In every message you send","Only after the customer has booked three times","Immediately at the start of the appointment"]'::jsonb,
    'After a positive experience when the customer is satisfied',
    'Only ask for referrals after a positive experience. If the appointment did not go well, asking for introductions feels tone-deaf. The referral request should come when the customer is most satisfied with your service.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How should you handle third-party contact information in a referral request?', 
    '["Ask the customer to provide the person''s email and phone number","Look up the person''s contact details online and reach out directly","Third-party privacy is not a concern for referrals","Ask the customer to introduce you or share your information instead"]'::jsonb,
    'Ask the customer to introduce you or share your information instead',
    'Never ask customers to share another person''s private contact details without permission. Instead, provide a shareable link or ask them to make an introduction. Respect for privacy builds trust.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How many referral requests should you include in your follow-up sequence?', 
    '["One in every message for maximum results","None — referrals should only happen organically","One well-timed request is enough","At least three to ensure they see it"]'::jsonb,
    'One well-timed request is enough',
    'One well-timed referral request is enough. Repeatedly asking for introductions feels desperate and can damage the customer relationship. A single, respectful ask at the right moment is far more effective.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

