-- Insert Quiz Questions for Lesson: Present the Next Useful Service

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 21 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 21 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'present-next-useful-service' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson present-next-useful-service not found in module 21';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should the next-service offer feel like to the customer?', 
    '["A condition for receiving future appointments","An invitation to continue making progress on their goals","A limited-time discount they cannot refuse","A mandatory upgrade they must purchase"]'::jsonb,
    'An invitation to continue making progress on their goals',
    'The next-service offer should feel like an invitation to continue progress, not a demand. When the service is genuinely relevant and presented respectfully, customers appreciate the suggestion rather than feeling pressured.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How should you choose which service to offer?', 
    '["Always offer the most expensive service","Match the service to the customer''s stated goals","Offer whatever service you are promoting this month","Rotate through services randomly"]'::jsonb,
    'Match the service to the customer''s stated goals',
    'Choose a package, workshop, retainer, or related service based on the customer''s stated goals. The better the fit between their needs and your offer, the more likely they are to be genuinely interested.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How long should you wait after the referral request before sending the next-offer message?', 
    '["Only if they do not respond to the referral request","One week","Immediately after the referral request","Approximately two days"]'::jsonb,
    'Approximately two days',
    'Wait approximately two days after the referral request. This spaces out your messages and gives each one room to breathe. Sending messages too close together feels overwhelming and reduces engagement.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;

