        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Stop, Test, and Improve',
      lesson_number = 7,
      sort_order = 7,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Stop, Test, and Improve';
