END $$;


-- Insert Quiz Questions for Lesson: Stop, Test, and Improve

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 21 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 21 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'stop-test-and-improve' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson stop-test-and-improve not found in module 21';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why are stop conditions essential in a follow-up workflow?', 
    '["They reduce the total number of messages sent","They prevent irrelevant messages after the customer takes action","They are required by law in all countries","They make the workflow run faster"]'::jsonb,
    'They prevent irrelevant messages after the customer takes action',
    'Stop conditions prevent redundant or irrelevant messages. If a customer already rebooked, they should not receive another rebooking invitation. Stop conditions respect customer actions and protect the relationship.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do when a customer opts out or unsubscribes?', 
    '["Immediately stop all promotional messages and honour their preferences","Continue sending messages on a different channel","Send one final message asking why they unsubscribed","Add them to a different workflow instead"]'::jsonb,
    'Immediately stop all promotional messages and honour their preferences',
    'When a customer opts out, immediately stop all promotional messages and honour their preferences without exception. Continuing to message someone who unsubscribed damages trust and may violate regulations.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you test the workflow with a sample contact before going live?', 
    '["Sample contacts are required by GoHighLevel","Testing is only needed for complex workflows","Testing is a waste of time for simple sequences","To verify triggers, timing, content, links, and stop conditions"]'::jsonb,
    'To verify triggers, timing, content, links, and stop conditions',
    'Testing with a sample contact lets you experience the sequence as a customer would. You can verify timing, check content and personalization, test all links, and confirm stop conditions work before real contacts enter the workflow.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
